package com.bank.flink.eager;

// Holds the out-of-orderness delay. Small delay = eager, large = relaxed.
class WatermarkPolicy {
    private final long outOfOrdernessMillis;
    private long maxSeen = Long.MIN_VALUE;

    WatermarkPolicy(long outOfOrdernessMillis) {
        this.outOfOrdernessMillis = outOfOrdernessMillis;
    }

    void onEvent(long ts) {
        if (ts > maxSeen) maxSeen = ts;
    }

    long watermark() {
        return maxSeen == Long.MIN_VALUE ? Long.MIN_VALUE : maxSeen - outOfOrdernessMillis;
    }

    boolean isEager() { return outOfOrdernessMillis <= 1000; }
}
