package com.bank.flink.eager;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.logging.Logger;

// Buckets movements into fixed windows, fires on watermark, drops late.
class WindowAggregator {
    private static final Logger log = Logger.getLogger(WindowAggregator.class.getName());

    private final long windowSize;
    private final WatermarkPolicy policy;
    private final Map<Long, Integer> counts = new HashMap<>();
    private final Map<Long, BigDecimal> totals = new HashMap<>();
    private final Set<Long> fired = new HashSet<>();
    private int dropped = 0;

    WindowAggregator(long windowSize, WatermarkPolicy policy) {
        this.windowSize = windowSize;
        this.policy = policy;
    }

    private long windowStart(long ts) { return ts - (ts % windowSize); }

    void process(Movement m) {
        policy.onEvent(m.getEventTimeMillis());
        long start = windowStart(m.getEventTimeMillis());
        long end = start + windowSize;

        if (policy.watermark() >= end) {
            // window already fired under this (eager/relaxed) policy -> late
            dropped++;
            log.warning(() -> "DROPPED late movement " + m.getAccountId()
                    + " ts=" + m.getEventTimeMillis() + " window=" + start);
            return;
        }
        counts.merge(start, 1, Integer::sum);
        totals.merge(start, m.getAmount(), BigDecimal::add);
    }

    // Fire windows the watermark has now passed.
    void fireReady() {
        long wm = policy.watermark();
        for (Long start : counts.keySet()) {
            long end = start + windowSize;
            if (wm >= end && !fired.contains(start)) {
                fired.add(start);
                log.info(() -> "FIRE window=" + start + " count=" + counts.get(start)
                        + " total=" + totals.get(start));
            }
        }
    }

    int getDropped() { return dropped; }
}
