package com.bank.flink.eager;

import java.math.BigDecimal;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: same stream under eager vs relaxed watermark.
public class EagerVsRelaxedDemo {
    private static final Logger log = Logger.getLogger(EagerVsRelaxedDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new EagerLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Movement[] stream = new Movement[] {
            new Movement("SAV2001", new BigDecimal("100"), 1_000),
            new Movement("SAV2001", new BigDecimal("200"), 3_000),
            new Movement("SAV2001", new BigDecimal("300"), 12_000),  // advances watermark to next window
            new Movement("SAV2001", new BigDecimal("400"), 5_000),   // straggler for window [0,10s)
            new Movement("SAV2001", new BigDecimal("500"), 20_000)
        };

        log.info(() -> "=== EAGER watermark (ooo=200ms) ===");
        run(stream, 200L);

        log.info(() -> "=== RELAXED watermark (ooo=30000ms) ===");
        run(stream, 30_000L);
    }

    private static void run(Movement[] stream, long ooo) {
        WatermarkPolicy policy = new WatermarkPolicy(ooo);
        WindowAggregator agg = new WindowAggregator(10_000L, policy);
        for (Movement m : stream) {
            agg.process(m);
            agg.fireReady();
        }
        log.info(() -> "Dropped stragglers = " + agg.getDropped());
    }
}

// ─── Would be in EagerLogFormatter.java in a real project ───
class EagerLogFormatter extends Formatter {
    @Override
    public String format(LogRecord record) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(record.getMillis()),
                record.getLevel().getName(),
                record.getMessage());
    }
}
